import * as React from 'react'
import { Cookie } from 'lucide-react'

import { Portal } from '~/components/primitives/portal'
import { cx } from '~/lib/cx'
import { safeHref } from '~/lib/security'
import { Button } from './button'
import styles from './cookie-consent.module.scss'

export function CookieConsent({
  storageKey = 'vz.cookie-consent',
  title = 'We use cookies',
  description = 'Essential cookies keep the app working. Analytics cookies are optional.',
  policyHref = '/privacy',
  policyLabel = 'Privacy policy',
  onAccept,
  onReject,
  className,
}: {
  storageKey?: string
  title?: string
  description?: string
  policyHref?: string
  policyLabel?: string
  onAccept?: () => void
  onReject?: () => void
  className?: string
}) {
  const [visible, setVisible] = React.useState(() => {
    if (typeof window === 'undefined') return false
    try {
      return !window.localStorage.getItem(storageKey)
    } catch {
      return true
    }
  })

  const decide = (value: 'accepted' | 'rejected') => {
    try {
      window.localStorage.setItem(storageKey, value)
    } catch {
      // Storage may be blocked; still dismiss for this session.
    }
    setVisible(false)
    if (value === 'accepted') onAccept?.()
    else onReject?.()
  }

  if (!visible) return null
  const href = safeHref(policyHref)

  return (
    <Portal>
      <div role="region" aria-label="Cookie consent" className={cx(styles.root, className)}>
        <div className={styles.layout}>
          <Cookie className={styles.icon} aria-hidden />
          <div className={styles.body}>
            <p className={styles.title}>{title}</p>
            <p className={styles.description}>
              {description}{' '}
              {href ? (
                <a href={href} className={styles.link}>
                  {policyLabel}
                </a>
              ) : null}
            </p>
            <div className={styles.actions}>
              <Button size="sm" onClick={() => decide('accepted')}>
                Accept all
              </Button>
              <Button size="sm" variant="outline" onClick={() => decide('rejected')}>
                Essential only
              </Button>
            </div>
          </div>
        </div>
      </div>
    </Portal>
  )
}

@use 'styles' as vz;

.root {
  position: fixed;
  right: vz.space(3);
  bottom: calc(#{vz.space(3)} + env(safe-area-inset-bottom, 0px));
  left: vz.space(3);
  z-index: vz.z('toast');
  max-width: 42rem;
  margin-inline: auto;
  padding: vz.space(4);
  border: 1px solid vz.color('border', 0.72);
  border-radius: vz.radius('2xl');
  background: vz.color('popover', 0.88);
  color: vz.color('popover-foreground');
  box-shadow: vz.elevation(3);
  backdrop-filter: blur(20px) saturate(180%);
  animation: vz-consent-in 320ms vz.ease('spring') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.layout {
  display: flex;
  align-items: flex-start;
  gap: vz.space(3);
}

.icon {
  flex: none;
  width: vz.space(9);
  height: vz.space(9);
  padding: vz.space(2);
  border-radius: vz.radius('full');
  background: vz.color('warning', 0.14);
  color: vz.color('warning');
  margin-top: 1px;
}

.body {
  flex: 1;
  min-width: 0;
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 650;
  line-height: 1.35;
}

.description {
  margin: vz.space(1) 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.55;
}

.link {
  color: vz.color('foreground');
  text-underline-offset: 2px;
  text-decoration: underline;

  @include vz.hover {
    color: vz.color('primary');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: vz.space(2);
  padding-top: vz.space(3);
}

@include vz.up('sm') {
  .root {
    right: vz.space(4);
    bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
    left: vz.space(4);
    padding: vz.space(4) vz.space(5);
  }

  .actions {
    justify-content: flex-start;
  }
}

@keyframes vz-consent-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
